Object.assign(EXC_NOTE, {
  offer:"o 在 offer 裡唸 /ɔ/，嘴巴張圓，像 off、coffee 的 o，不唸短 o /ɑ/ 也不唸長 o。",
  deadline:"ea 在 dead 裡唸短 e /ɛ/，和 bread、head、ready 一樣，不唸長長的 /iː/。",
  survey:"ey 在 survey 裡唸 /eɪ/，像字母 A，和 they、grey 一樣，不唸 key 的 /iː/。",
  million:"ll 後面的 i 不唸「一」，而是滑成 /j/ 的聲音，和 o 連起來唸 /jən/：MIL-lion。",
  situation:"t 後面接 u 時，t 常變成 /tʃ/，像「去」的子音，所以唸 sit-chu-A-tion。",
  therefore:"ere 在 there、where、therefore 裡唸 /ɛr/，像「欸爾」，不唸 here 的 /ɪr/。",
  although:"ough 在 although 裡唸長 o /oʊ/，gh 不發音；al 唸 /ɔl/。重音在後面：al-THOUGH。",
  though:"ough 是英文最難的字母組合之一，在 though 裡唸長 o /oʊ/，gh 不發音。",
  "for example":"x 在 example 裡唸 /gz/，喉嚨要震動：ig-ZAM-ple；for 在片語裡要弱讀成 /fɚ/。",
  "even though":"ough 在 though 裡唸長 o /oʊ/，gh 不發音；th 是有聲的 /ð/。",
  coupon:"ou 在 coupon 裡唸長長的 /uː/，像 you、soup，不唸 house 的 /aʊ/：KOO-pon。",
  warning:"w 後面的 ar 常唸 /ɔr/，像 war、warm、warning，不唸 car 的 /ɑr/。",
  receive:"c 後面的 ei 唸長 e /iː/，記住「i 在 e 前面，除了在 c 後面」：receive、ceiling。",
  during:"u 在 during 裡唸短短的 /ʊ/（也有人唸 /jʊ/），不唸 run 的 /ʌ/。"
});
