const J3_X_PHONICS_CLASS = {
p1:[
 {say:"同學好！會考聽力的句子，外國人不會一個字一個字慢慢唸，而是連在一起說。今天教你兩個祕密：連音和弱讀。先聽：{Pick it up.} 聽起來像不像「pi-ki-tup」？", board:[["Pick it up.",["k i","t u"],false,true],["→ pi-ki-tup",[]]]},
 {say:"連音規則一：前一個字的最後是子音，下一個字的開頭是母音，兩個就會手牽手連起來！{check it out}、{turn it off}、{an apple}。", board:[["check it out → che-ki-tout",["k i","t o"],false,true],["turn it off → tur-ni-toff",["n i","t o"],false,true],["an apple → a-napple",["n a"],false,true]]},
 {say:"口訣先記！", chant:"子音碰母音，手牽手連起來！"},
 {ask:{say:"聽聽看！", q:"聽到「a-nap-ple」，原本是哪兩個字？", opts:["a nap pull","an apple","and apple"], ans:1,
   ok:"答對了！an 的 n 和 apple 的 a 連在一起，聽起來像 a-napple。",
   bad:{0:"這是被連音騙了！n 是 an 的尾巴，和 apple 連在一起了。",2:"and 後面還有 d 的聲音，這裡只是 an 的 n 連過去。"},
   again:{q:"聽到「tur-ni-toff」，原本是？", opts:["turn it off","turning off","turn a tough"], ans:0, exp:"turn it off：n 連 i、t 連 o。"}}},
 {say:"連音規則二：前一個字的結尾和下一個字的開頭是一樣（或很像）的子音，只唸一次就好！{bus stop}、{next time}、{good day}。", board:[["bus stop → bu-stop",["s s"],false,true],["next time → nex-time",["t t"],false,true],["good day → goo-day",["d d"],false,true]]},
 {ask:{q:"聽到 bus stop，兩個 s 聽起來怎麼樣？", opts:["兩個 s 都唸得很清楚","兩個 s 合成一個：bu-stop","兩個 s 都不唸：bu-top"], ans:1,
   ok:"讚！相同的子音碰在一起只唸一次，聽起來是 bu-stop。",
   bad:{0:"說話快的時候，兩個一樣的子音會合成一個，不會分開唸兩次。",2:"s 不會完全消失，只是兩個合成一個。"},
   again:{q:"next time 的兩個 t，聽起來？", opts:["兩個 t 都很清楚","t 都不見了","只聽到一個 t"], ans:2, exp:"next 的 t 和 time 的 t 合成一個。"}}},
 {say:"接下來是弱讀。句子裡不重要的小字，像 {and}、{of}、{to}、{for}、{can}，會唸得又輕又快。{salt and pepper} 的 and 只剩下 n；{a cup of tea} 的 of 只剩下 /ə/。", board:[["salt and pepper → salt'n pepper",["and"],false,true],["a cup of tea → a cuppa tea",["of"],false,true],["I want to go. → to 唸 /tə/",["to"],false,true]]},
 {say:"弱讀的口訣！", chant:"小字唸得輕又快，重要的字才大聲！"},
 {say:"會考聽力最經典的陷阱：{can} 和 {can't}！can 在句子裡弱讀成 /kən/，後面的動詞比較重；can't 的 t 常常聽不到，可是母音 /æ/ 唸得又重又長。", board:[["I can swim. → I /kən/ SWIM",["can"],false,true],["I can't swim. → I /KÆNT/ swim",["can't"],false,true]]},
 {ask:{q:"聽到 I /kən/ SWIM.（can 輕輕的，swim 比較重），意思是？", opts:["我會游泳","我不會游泳","我在游泳"], ans:0,
   ok:"正確！can 弱讀成 /kən/，重音在 swim，是肯定的「會」。",
   bad:{1:"can't 的母音會唸得又重又長，這裡 can 是輕輕的 /kən/，是肯定句。",2:"「正在游泳」要說 I'm swimming，這裡是 can。"},
   again:{q:"聽到 I /KÆN/ swim.（can 唸得又重又長），意思最可能是？", opts:["我會游泳","我不會游泳","我想游泳"], ans:1, exp:"can't 的 t 常聽不到，但母音唸得重又長，所以是「不會」。"}}},
 {say:"最後一個：t 夾在兩個母音中間，美式英文會唸得很輕，像 /d/。{water} 像 wa-der，{get up} 像 ge-dup，{a lot of} 像 a-la-dof。", board:[["water → wa-der",["t"],false,true],["get up → ge-dup",["t u"],false,true],["a lot of → a-la-dof",["t o"],false,true]]},
 {ask:{say:"最後一題！", q:"聽到「ge-dup」，原本是？", opts:["good up","get a cup","get up"], ans:2,
   ok:"完美！get 的 t 夾在母音中間變輕，和 up 連起來：ge-dup。",
   bad:{0:"good 的母音是 /ʊ/，這裡聽到的是 /ɛ/，是 get。",1:"get a cup 會聽到 cup 的 /k/，這裡只有 up。"},
   again:{q:"聽到「wa-der」，最可能是？", opts:["water","wonder","wider"], ans:0, exp:"water 的 t 夾在母音中間，美式唸成像 /d/。"}}},
 {say:"連音和弱讀過關！記住：子音碰母音手牽手；一樣的子音只唸一次；小字輕又快；can 輕、can't 重；t 夾在母音中間變輕。下一課來練會考最愛考的數字！", end:true}
],
p2:[
 {say:"同學好！會考聽力幾乎每一回都會考數字：幾點、多少錢、幾月幾號、多少人。今天教你怎麼聽才不會錯！", board:[["時間　價錢　日期　數量",[]]]},
 {say:"第一關：{-teen} 和 {-ty}！13 到 19 的 teen 重音在後面，而且拉得長長的：{thirTEEN}；30、40、50 的 ty 重音在前面，ty 短短的：{THIRty}。", board:[["thirteen / thirty",["teen","ty"],false,true],["fifteen / fifty",["teen","ty"],false,true],["nineteen / ninety",["teen","ty"],false,true]]},
 {say:"口訣大聲唸！", chant:"teen 重音在後面拉長長，ty 重音在前面短短的！"},
 {ask:{say:"聽聽看！", q:"聽到 fif-TEEN（重音在後面，拉長），是哪個數字？", opts:["15","50","5"], ans:0,
   ok:"答對！重音在後面、拉長的是 teen：fifteen 15。",
   bad:{1:"50 是 FIF-ty，重音在前面，ty 短短的。",2:"5 是 five，只有一個音節。"},
   again:{q:"聽到 FOR-ty（重音在前面，ty 短短的），是？", opts:["14","40","4"], ans:1, exp:"重音在前面的是 ty：forty 40。"}}},
 {say:"第二關：時間。{seven fifteen} 也可以說 {a quarter past seven}；{seven thirty} 是 {half past seven}；{seven forty-five} 是 {a quarter to eight}。past 是「過了」，to 是「差幾分到」！", board:[["7:15 = a quarter past seven",["past"],false,true],["7:30 = half past seven",["past"],false,true],["7:45 = a quarter to eight",["to"],false,true]]},
 {ask:{q:"聽到 a quarter to nine，是幾點？", opts:["9:15","8:45","9:45"], ans:1,
   ok:"讚！to 是「差」，差十五分到九點，就是 8:45。",
   bad:{0:"9:15 是 a quarter past nine，past 才是「過了」。",2:"9:45 是 a quarter to ten。to 是「差幾分到」，所以要往前算。"},
   again:{q:"聽到 half past six，是幾點？", opts:["6:30","5:30","6:50"], ans:0, exp:"half past six 是六點過了一半，就是 6:30。"}}},
 {say:"第三關：價錢。{fifteen fifty} 是 $15.50；{twelve hundred} 是 $1,200。在美國，一千多的數字常常兩位兩位唸，要特別注意！", board:[["$15.50 = fifteen fifty",[]],["$1,200 = twelve hundred = one thousand two hundred",["hundred"],false,true]]},
 {ask:{q:"聽到 twelve hundred dollars，是多少錢？", opts:["$120","$1,200","$12,000"], ans:1,
   ok:"正確！twelve hundred = 12 個一百 = 1,200。",
   bad:{0:"$120 是 one hundred and twenty。",2:"$12,000 是 twelve thousand。"},
   again:{q:"在便利商店買飲料，聽到 It's two ninety-nine. 價錢最可能是？", opts:["$2.99","$299","$29.9"], ans:0, exp:"two ninety-nine 是兩元九十九分，$2.99。"}}},
 {say:"第四關：日期。日期要唸序數：{first}、{second}、{third}、{twentieth}。{May 20} 唸 {May twentieth} 或 {the twentieth of May}。年份通常兩位兩位唸：1998 是 {nineteen ninety-eight}，2025 是 {twenty twenty-five}。", board:[["May 20 = May twentieth",["th"],false,true],["June 3 = the third of June",["third"],false,true],["1998 = nineteen ninety-eight",[]]]},
 {say:"這也編成口訣！", chant:"日期唸序數，年份兩兩唸！"},
 {ask:{q:"聽到 the third of June，日期是？", opts:["6月3日","3月6日","6月13日"], ans:0,
   ok:"太好了！third 是第三，June 是六月，所以是 6 月 3 日。",
   bad:{1:"June 是六月，third 是日期，順序不要搞反了。",2:"13 日是 thirteenth，這裡是 third。"},
   again:{q:"年份 2008 最常怎麼唸？", opts:["twenty eight","two thousand (and) eight","two zero zero eight"], ans:1, exp:"2000 到 2009 年通常唸 two thousand (and) ……。"}}},
 {say:"會考聽力常常不是直接說答案，而是要你算一下！像「表演七點半開始，但我們要提早十五分鐘到」。所以聽題目前，先看選項，把數字圈起來，邊聽邊算。", board:[["The show starts at 7:30, but we should be there 15 minutes early.",["7:30","15 minutes early"]]]},
 {ask:{say:"最後挑戰！", q:"聽到：The show starts at seven thirty, but we should be there fifteen minutes early. 他們要幾點到？", opts:["7:15","7:30","7:45"], ans:0,
   ok:"完美！7:30 提早 15 分鐘，就是 7:15。",
   bad:{1:"7:30 是表演開始的時間，他們要提早到。",2:"early 是提早，要往前算，不是往後加。"},
   again:{q:"聽到：The ticket is 300 dollars, but students get 50 dollars off. 學生要付多少？", opts:["$350","$250","$300"], ans:1, exp:"50 dollars off 是便宜五十元：300 - 50 = 250。"}}},
 {say:"數字聽力過關！複習：teen 重音在後拉長長、ty 重音在前短短的；past 是過了、to 是差；年份兩兩唸；日期唸序數；聽到 early、off、more 要記得算一下。下一課來練容易聽錯的字！", end:true}
],
p3:[
 {say:"同學好！會考聽力有一種陷阱：選項裡放一個「聽起來很像」的字。今天教你分辨同音字和相近音，不再被騙！", board:[["hear / here　live / leave　full / fool",[]]]},
 {say:"第一種：同音字，唸法完全一樣，只能靠句子的意思判斷！{hear} 和 {here}、{right} 和 {write}、{buy} 和 {by}、{meet} 和 {meat}、{week} 和 {weak}。", board:[["hear 聽 / here 這裡",["hear","here"]],["write 寫 / right 對的",["write","right"]],["meet 見面 / meat 肉",["meet","meat"]]]},
 {say:"口訣先記！", chant:"同音不同字，聽上下文來分辨！"},
 {ask:{say:"聽聽看！", q:"電話裡聽到 I can't /hɪr/ you. 這個字是？", opts:["here","hear","hair"], ans:1,
   ok:"答對！「我聽不到你」，是 hear。",
   bad:{0:"here 是「這裡」，can't here you 不合文法，這裡要動詞 hear。",2:"hair 唸 /hɛr/，嘴巴比較開，而且 can't hair you 不合理。"},
   again:{q:"老師說 Please /raɪt/ your name here. 這個字是？", opts:["write","right","ride"], ans:0, exp:"「請寫下你的名字」，是 write。"}}},
 {say:"第二種：長短音。短 i /ɪ/ 短短輕輕的；長 e /iː/ 嘴巴往兩邊拉，聲音拉長。{live} 和 {leave}、{ship} 和 {sheep}、{sit} 和 {seat}。", board:[["live /lɪv/ — leave /liːv/",["i","ea"],false,true],["ship /ʃɪp/ — sheep /ʃiːp/",["i","ee"],false,true],["sit /sɪt/ — seat /siːt/",["i","ea"],false,true]]},
 {ask:{q:"聽到 We /liːv/ at six.（長長的 /iː/），是？", opts:["live","love","leave"], ans:2,
   ok:"讚！長長的 /iː/ 是 leave：我們六點出發。",
   bad:{0:"live 是短短的 /ɪ/，這裡聽到的是長音。",1:"love 的母音是 /ʌ/，像「ㄜ」，不一樣。"},
   again:{q:"聽到 There are many /ʃiːp/ on the farm.（長長的 /iː/），是？", opts:["ship","sheep","shop"], ans:1, exp:"長音 /iː/ 是 sheep 綿羊；農場上也比較合理。"}}},
 {say:"第三種：oo 的長短音。短 oo /ʊ/ 短短的；長 oo /uː/ 嘴巴嘟起來拉長。{full} 和 {fool}、{pull} 和 {pool}。", board:[["full /fʊl/ — fool /fuːl/",["u","oo"],false,true],["pull /pʊl/ — pool /puːl/",["u","oo"],false,true]]},
 {ask:{q:"聽到 The bottle is /fʊl/.（短短的 /ʊ/），是？", opts:["full","fool","fall"], ans:0,
   ok:"正確！短短的 /ʊ/ 是 full：瓶子滿了。",
   bad:{1:"fool 是長長的 /uː/，而且「瓶子是笨蛋」不合理。",2:"fall 唸 /ɔ/，嘴巴張比較大。"},
   again:{q:"聽到 Let's swim in the /puːl/.（長長的 /uː/），是？", opts:["pull","pool","pole"], ans:1, exp:"長音 /uː/ 是 pool 游泳池。"}}},
 {say:"第四種：短 e /ɛ/ 和短 a /æ/。/æ/ 嘴巴張很大，像「欸」和「啊」的中間。{bed} 和 {bad}、{men} 和 {man}、{pen} 和 {pan}。", board:[["bed /bɛd/ — bad /bæd/",["e","a"],false,true],["men /mɛn/ — man /mæn/",["e","a"],false,true]]},
 {ask:{q:"聽到 Two /mɛn/ are talking.（嘴巴沒張很大的 /ɛ/），是？", opts:["man","main","men"], ans:2,
   ok:"太好了！/ɛ/ 是 men，而且 Two 和 are 也告訴你是複數。",
   bad:{0:"man 是 /æ/，嘴巴要張很大；而且 Two...are 是複數，要用 men。",1:"main 唸 /eɪ/，像字母 A。"},
   again:{q:"聽到 I had a /bæd/ day.（嘴巴張很大的 /æ/），是？", opts:["bed","bad","bid"], ans:1, exp:"/æ/ 是 bad：我今天很倒楣。"}}},
 {say:"第五種：咬舌頭的 th！{three} 和 {tree}、{think} 和 {sink}。th 要把舌頭輕輕放在牙齒中間送氣。", board:[["three — tree",["th"],false,true],["think — sink",["th"],false,true]]},
 {say:"把聽力重點編成口訣！", chant:"長短、開口、咬舌頭，三個重點聽清楚！"},
 {ask:{say:"最後一題！", q:"聽到 There are /θriː/ apples.（舌頭咬住），是？", opts:["three","tree","free"], ans:0,
   ok:"完美！咬舌頭的 /θ/ 是 three：有三個蘋果。",
   bad:{1:"tree 是 /t/，舌頭不用咬住；而且 There are ___ apples 要接數字。",2:"free 是 /f/，用上排牙齒碰下唇。"},
   again:{q:"聽到 I /θɪŋk/ so.（舌頭咬住），是？", opts:["sink","think","thing"], ans:1, exp:"I think so. 我想是吧。/θ/ 開頭、/k/ 結尾是 think。"}}},
 {say:"容易聽錯的字過關！記住：同音字看上下文；長短音聽長度；/æ/ 嘴巴張大；th 要咬舌頭。最後一課，我們來聽說話者的「語氣」！", end:true}
],
p4:[
 {say:"同學好！會考聽力很常問：{What does the woman mean?}（這位女士是什麼意思？）光聽單字不夠，還要聽「語調」！同一句話，語調不一樣，意思就不一樣。", board:[["Really? ↗（驚訝）",[]],["Really... ↘（不太相信）",[]]]},
 {say:"先複習基本語調：直述句語尾下降 ↘；Wh 問句（what、where、how）語尾也下降 ↘；Yes/No 問句語尾上揚 ↗。", board:[["I live in Taipei. ↘",[]],["Where do you live? ↘",["Where"]],["Do you live in Taipei? ↗",["Do"]]]},
 {ask:{q:"Where do you live? 語尾通常是？", opts:["上揚 ↗","下降 ↘","平平的"], ans:1,
   ok:"答對！Wh 開頭的問句，語尾通常下降。",
   bad:{0:"上揚是 Yes/No 問句，Where 開頭的問句語尾下降。",2:"英文問句的語尾會有明顯的上揚或下降，不會平平的。"},
   again:{q:"Do you like it? 語尾通常是？", opts:["下降 ↘","平平的","上揚 ↗"], ans:2, exp:"Do 開頭的 Yes/No 問句，語尾上揚。"}}},
 {say:"第一種情緒：驚訝！音調高高的、突然揚起來：{Really?}、{You won?}、{No way!} 聽起來很興奮。", board:[["Really? ↗↗",[]],["You won? ↗↗",[]]]},
 {say:"第二種：懷疑、不相信。語調拉長、慢慢的，常常先降再升：{Oh, really...}、{Sure...}。第三種：說反話。用低沉下降的語調說好話，其實是不開心：{Great. Just great.}", board:[["Oh, really... ↘↗（不太相信）",[]],["Great. Just great. ↘（其實很糟）",[]]]},
 {say:"口訣記起來！", chant:"高高上揚是驚訝，拉長拖慢是懷疑，低低沉沉是反話！"},
 {ask:{q:"朋友說 I got 100 on the test! 你高高揚起語調回答 Really?↗，意思是？", opts:["我很驚訝，好棒！","我不相信你","我很生氣"], ans:0,
   ok:"正確！高高揚起的 Really? 是驚訝和替對方開心。",
   bad:{1:"不相信的 Really 會拉長、拖慢，不會高高揚起。",2:"生氣的語氣通常低沉、用力，不是高高揚起。"},
   again:{q:"下雨又錯過公車，他低沉地說 Great. Just great.↘，意思是？", opts:["他很開心","他覺得天氣很好","他其實很不開心"], ans:2, exp:"低沉下降的 Great 是說反話，其實很糟。"}}},
 {say:"再來是客氣的請求。命令句語尾下降，聽起來很直接：{Open the window.} 客氣的請求用 {Could you...?}、{Would you mind...?}，語尾上揚，再加上 {please}，聽起來就很有禮貌。", board:[["Open the window. ↘（直接）",[]],["Could you open the window, please? ↗（客氣）",["Could you","please"]],["Would you mind opening the window? ↗",["Would you mind"]]]},
 {ask:{q:"哪一句聽起來最客氣？", opts:["Open the window.↘","Could you open the window, please?↗","You open the window.↘"], ans:1,
   ok:"讚！Could you...please? 加上上揚的語調，最有禮貌。",
   bad:{0:"命令句語尾下降，聽起來比較直接，不夠客氣。",2:"You open the window. 像在命令別人，最不禮貌。"},
   again:{q:"Would you mind ___ the door? 客氣地請別人關門，空格要填？", opts:["closing","to close","close"], ans:0, exp:"mind + V-ing：Would you mind closing the door?"}}},
 {say:"最後一招：重音放在哪個字，就是在強調那個字！{I didn't eat YOUR cake.} 強調 YOUR，意思是「我吃的不是你的蛋糕」，暗示吃了別人的。", board:[["I didn't eat YOUR cake.（吃了別人的）",["YOUR"]],["I didn't EAT your cake.（只是拿起來，沒吃）",["EAT"]],["I didn't eat your CAKE.（吃了你別的東西）",["CAKE"]]]},
 {ask:{q:"聽到 TOM bought the tickets.（TOM 唸得特別重），想強調什麼？", opts:["是湯姆買的，不是別人","湯姆是買的，不是借的","湯姆買的是票，不是別的"], ans:0,
   ok:"完美！重音在 TOM，強調「是湯姆，不是別人」。",
   bad:{1:"要強調「買」的話，重音會放在 bought。",2:"要強調「票」的話，重音會放在 tickets。"},
   again:{q:"聽到 I didn't eat YOUR cake.（YOUR 特別重），意思最可能是？", opts:["我沒吃任何蛋糕","我吃了別人的蛋糕，不是你的","我做了你的蛋糕"], ans:1, exp:"重音在 YOUR，強調不是你的，暗示吃了別人的。"}}},
 {say:"會考聽力的小技巧：題目問 {What does the man mean?} 或 {How does the woman feel?} 時，不要只抓單字，要聽語調和重音。說 Great 不一定是開心，說 Sure 不一定是同意喔！", board:[["What does the man mean?",[]],["How does the woman feel?",[]]]},
 {say:"會考發音和聽力全部上完了！總複習：子音碰母音要連音、小字要弱讀；teen 和 ty 聽重音；同音字看上下文；語調高揚是驚訝、拉長是懷疑、低沉是反話。祝你會考聽力拿滿分！快去玩「拼字挑戰」試試身手吧！", end:true}
]};

/* ---------- 單字插圖（抽象的字用單字陣列第 7 欄的概念卡） ---------- */
const j3xPaper = (x, y, w, h, c = "#fff") => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="2" fill="${c}" stroke="#e5e7eb"/>`;
